INSERT INTO practice_sets(skill,part_no,title,instructions,difficulty,is_published) SELECT 'READING',7,'Part 7 — Cấp 1','[READING_PART7_LEVEL:1] Chọn đủ câu trong nhóm bài đọc để xem kết quả.','EASY',TRUE WHERE NOT EXISTS(SELECT 1 FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:1]%');
INSERT INTO practice_passages(practice_set_id,passage_text,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:1]%' ORDER BY id LIMIT 1),'{"title": "Community Library Notice", "documents": [{"title": "Saturday opening hours", "title_vi": "Giờ mở cửa thứ Bảy", "lines": [{"en": "From May 3, Greenfield Library will open at 9 a.m. on Saturdays instead of 10 a.m. Closing time remains 5 p.m.", "vi": "Từ ngày 3 tháng 5, Thư viện Greenfield sẽ mở cửa lúc 9 giờ sáng thứ Bảy thay vì 10 giờ. Giờ đóng cửa vẫn là 5 giờ chiều."}, {"en": "Members can reserve books online. Reserved books must be collected within three days. Please bring your membership card.", "vi": "Thành viên có thể đặt sách trực tuyến. Sách đã đặt phải được nhận trong vòng ba ngày. Vui lòng mang thẻ thành viên."}]}], "glossary": {"reserve": "đặt trước", "collected": "được nhận", "membership": "tư cách thành viên", "remains": "vẫn giữ nguyên"}}',1 WHERE NOT EXISTS(SELECT 1 FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:1]%' ORDER BY id LIMIT 1) AND sort_order=1);
INSERT INTO practice_questions(practice_set_id,passage_id,question_text,explanation,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:1]%' ORDER BY id LIMIT 1),(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:1]%' ORDER BY id LIMIT 1) AND sort_order=1 ORDER BY id LIMIT 1),'What will change on May 3?','{"translation": "Điều gì sẽ thay đổi vào ngày 3 tháng 5?", "options_vi": {"A": "Giờ mở cửa thứ Bảy", "B": "Phí thành viên", "C": "Giờ đóng cửa", "D": "Địa chỉ thư viện"}, "evidence": "From May 3, Greenfield Library will open at 9 a.m. on Saturdays instead of 10 a.m.", "explanation": "Giờ mở cửa được đổi từ 10 giờ sang 9 giờ sáng. Thông báo nói giờ đóng cửa không đổi và không đề cập thay đổi phí hay địa chỉ.", "analysis": {"A": "Đúng. Giờ mở cửa được đổi từ 10 giờ sang 9 giờ sáng. Thông báo nói giờ đóng cửa không đổi và không đề cập thay đổi phí hay địa chỉ.", "B": "Không phù hợp với dẫn chứng: Phí thành viên. Giờ mở cửa được đổi từ 10 giờ sang 9 giờ sáng. Thông báo nói giờ đóng cửa không đổi và không đề cập thay đổi phí hay địa chỉ.", "C": "Không phù hợp với dẫn chứng: Giờ đóng cửa. Giờ mở cửa được đổi từ 10 giờ sang 9 giờ sáng. Thông báo nói giờ đóng cửa không đổi và không đề cập thay đổi phí hay địa chỉ.", "D": "Không phù hợp với dẫn chứng: Địa chỉ thư viện. Giờ mở cửa được đổi từ 10 giờ sang 9 giờ sáng. Thông báo nói giờ đóng cửa không đổi và không đề cập thay đổi phí hay địa chỉ."}}',147 WHERE NOT EXISTS(SELECT 1 FROM practice_questions WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:1]%' ORDER BY id LIMIT 1) AND passage_id=(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:1]%' ORDER BY id LIMIT 1) AND sort_order=1 ORDER BY id LIMIT 1) AND sort_order=147);
