INSERT INTO practice_questions(practice_set_id,passage_id,question_text,explanation,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:1]%' ORDER BY id LIMIT 1),(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:1]%' ORDER BY id LIMIT 1) AND sort_order=1 ORDER BY id LIMIT 1),'What should members bring when collecting books?','{"translation": "Thành viên cần mang gì khi nhận sách?", "options_vi": {"A": "Biên lai", "B": "Thẻ thành viên", "C": "Bản in đặt sách", "D": "Ảnh"}, "evidence": "Please bring your membership card.", "explanation": "Thông báo yêu cầu mang thẻ thành viên; không yêu cầu biên lai, bản in hoặc ảnh.", "analysis": {"A": "Không phù hợp với dẫn chứng: Biên lai. Thông báo yêu cầu mang thẻ thành viên; không yêu cầu biên lai, bản in hoặc ảnh.", "B": "Đúng. Thông báo yêu cầu mang thẻ thành viên; không yêu cầu biên lai, bản in hoặc ảnh.", "C": "Không phù hợp với dẫn chứng: Bản in đặt sách. Thông báo yêu cầu mang thẻ thành viên; không yêu cầu biên lai, bản in hoặc ảnh.", "D": "Không phù hợp với dẫn chứng: Ảnh. Thông báo yêu cầu mang thẻ thành viên; không yêu cầu biên lai, bản in hoặc ảnh."}}',148 WHERE NOT EXISTS(SELECT 1 FROM practice_questions WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:1]%' ORDER BY id LIMIT 1) AND passage_id=(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:1]%' ORDER BY id LIMIT 1) AND sort_order=1 ORDER BY id LIMIT 1) AND sort_order=148);
