INSERT INTO practice_sets(skill,part_no,title,instructions,difficulty,is_published) SELECT 'READING',7,'Part 7 — Cấp 2','[READING_PART7_LEVEL:2] Chọn đủ câu trong nhóm bài đọc để xem kết quả.','EASY',TRUE WHERE NOT EXISTS(SELECT 1 FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:2]%');
INSERT INTO practice_passages(practice_set_id,passage_text,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:2]%' ORDER BY id LIMIT 1),'{"title": "Office Workshop", "documents": [{"title": "Email: Spreadsheet workshop", "title_vi": "Email: Buổi học bảng tính", "lines": [{"en": "To: All staff · From: Training Department · Subject: Friday workshop", "vi": "Gửi: Toàn thể nhân viên · Từ: Phòng đào tạo · Chủ đề: Buổi học thứ Sáu"}, {"en": "A spreadsheet workshop will be held in Room 302 this Friday from 2 to 4 p.m. It is designed for beginners. Bring a laptop; sample files will be provided.", "vi": "Buổi học bảng tính sẽ diễn ra tại phòng 302 thứ Sáu này từ 2 đến 4 giờ chiều. Khóa học dành cho người mới bắt đầu. Hãy mang máy tính xách tay; tệp mẫu sẽ được cung cấp."}, {"en": "To reserve a place, email training by Wednesday noon. There are only twelve seats. If the workshop is full, you will be offered a place in next month’s session.", "vi": "Để giữ chỗ, hãy gửi email cho phòng đào tạo trước trưa thứ Tư. Chỉ có mười hai chỗ. Nếu buổi học đã kín, bạn sẽ được đề nghị tham dự buổi tháng sau."}]}], "glossary": {"workshop": "buổi học thực hành", "beginners": "người mới bắt đầu", "provided": "được cung cấp", "seats": "chỗ ngồi", "reserve": "giữ chỗ"}}',1 WHERE NOT EXISTS(SELECT 1 FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:2]%' ORDER BY id LIMIT 1) AND sort_order=1);
INSERT INTO practice_questions(practice_set_id,passage_id,question_text,explanation,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:2]%' ORDER BY id LIMIT 1),(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:2]%' ORDER BY id LIMIT 1) AND sort_order=1 ORDER BY id LIMIT 1),'Who is the workshop intended for?','{"translation": "Buổi học dành cho ai?", "options_vi": {"A": "Lập trình viên kinh nghiệm", "B": "Người mới dùng bảng tính", "C": "Chỉ quản lý phòng ban", "D": "Khách hàng bên ngoài"}, "evidence": "It is designed for beginners.", "explanation": "Beginners là người mới bắt đầu sử dụng bảng tính, không phải nhóm chuyên gia hay khách hàng bên ngoài.", "analysis": {"A": "Không phù hợp với dẫn chứng: Lập trình viên kinh nghiệm. Beginners là người mới bắt đầu sử dụng bảng tính, không phải nhóm chuyên gia hay khách hàng bên ngoài.", "B": "Đúng. Beginners là người mới bắt đầu sử dụng bảng tính, không phải nhóm chuyên gia hay khách hàng bên ngoài.", "C": "Không phù hợp với dẫn chứng: Chỉ quản lý phòng ban. Beginners là người mới bắt đầu sử dụng bảng tính, không phải nhóm chuyên gia hay khách hàng bên ngoài.", "D": "Không phù hợp với dẫn chứng: Khách hàng bên ngoài. Beginners là người mới bắt đầu sử dụng bảng tính, không phải nhóm chuyên gia hay khách hàng bên ngoài."}}',147 WHERE NOT EXISTS(SELECT 1 FROM practice_questions WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:2]%' ORDER BY id LIMIT 1) AND passage_id=(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:2]%' ORDER BY id LIMIT 1) AND sort_order=1 ORDER BY id LIMIT 1) AND sort_order=147);
