INSERT INTO practice_questions(practice_set_id,passage_id,question_text,explanation,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:2]%' ORDER BY id LIMIT 1),(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:2]%' ORDER BY id LIMIT 1) AND sort_order=1 ORDER BY id LIMIT 1),'What must participants supply themselves?','{"translation": "Người tham dự phải tự chuẩn bị gì?", "options_vi": {"A": "Tệp mẫu", "B": "Bữa trưa", "C": "Máy tính xách tay", "D": "Máy chiếu"}, "evidence": "Bring a laptop; sample files will be provided.", "explanation": "Người tham gia mang máy tính; ban tổ chức cung cấp tệp mẫu. Bữa trưa và máy chiếu không được yêu cầu.", "analysis": {"A": "Không phù hợp với dẫn chứng: Tệp mẫu. Người tham gia mang máy tính; ban tổ chức cung cấp tệp mẫu. Bữa trưa và máy chiếu không được yêu cầu.", "B": "Không phù hợp với dẫn chứng: Bữa trưa. Người tham gia mang máy tính; ban tổ chức cung cấp tệp mẫu. Bữa trưa và máy chiếu không được yêu cầu.", "C": "Đúng. Người tham gia mang máy tính; ban tổ chức cung cấp tệp mẫu. Bữa trưa và máy chiếu không được yêu cầu.", "D": "Không phù hợp với dẫn chứng: Máy chiếu. Người tham gia mang máy tính; ban tổ chức cung cấp tệp mẫu. Bữa trưa và máy chiếu không được yêu cầu."}}',148 WHERE NOT EXISTS(SELECT 1 FROM practice_questions WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:2]%' ORDER BY id LIMIT 1) AND passage_id=(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:2]%' ORDER BY id LIMIT 1) AND sort_order=1 ORDER BY id LIMIT 1) AND sort_order=148);
