INSERT INTO practice_questions(practice_set_id,passage_id,question_text,explanation,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:2]%' ORDER BY id LIMIT 1),(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:2]%' ORDER BY id LIMIT 1) AND sort_order=1 ORDER BY id LIMIT 1),'What happens if all seats are taken?','{"translation": "Điều gì xảy ra nếu hết chỗ?", "options_vi": {"A": "Chuyển sang trực tuyến", "B": "Hoàn phí", "C": "Đổi phòng", "D": "Đề nghị một buổi khác"}, "evidence": "If the workshop is full, you will be offered a place in next month’s session.", "explanation": "Người đăng ký được đề nghị học vào tháng sau; email không nói chuyển hình thức, hoàn tiền hay đổi phòng.", "analysis": {"A": "Không phù hợp với dẫn chứng: Chuyển sang trực tuyến. Người đăng ký được đề nghị học vào tháng sau; email không nói chuyển hình thức, hoàn tiền hay đổi phòng.", "B": "Không phù hợp với dẫn chứng: Hoàn phí. Người đăng ký được đề nghị học vào tháng sau; email không nói chuyển hình thức, hoàn tiền hay đổi phòng.", "C": "Không phù hợp với dẫn chứng: Đổi phòng. Người đăng ký được đề nghị học vào tháng sau; email không nói chuyển hình thức, hoàn tiền hay đổi phòng.", "D": "Đúng. Người đăng ký được đề nghị học vào tháng sau; email không nói chuyển hình thức, hoàn tiền hay đổi phòng."}}',149 WHERE NOT EXISTS(SELECT 1 FROM practice_questions WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:2]%' ORDER BY id LIMIT 1) AND passage_id=(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:2]%' ORDER BY id LIMIT 1) AND sort_order=1 ORDER BY id LIMIT 1) AND sort_order=149);
