INSERT INTO practice_passages(practice_set_id,passage_text,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:3]%' ORDER BY id LIMIT 1),'{"title": "Delivery Follow-up", "documents": [{"title": "Order confirmation", "title_vi": "Xác nhận đơn hàng", "lines": [{"en": "Order 4821 · Customer: Linh Tran · Items: 6 desk lamps · Delivery: June 12, before noon · Address: 18 Park Road", "vi": "Đơn hàng 4821 · Khách hàng: Linh Tran · Hàng: 6 đèn bàn · Giao: ngày 12 tháng 6, trước trưa · Địa chỉ: 18 Park Road"}]}, {"title": "Email from Linh Tran", "title_vi": "Email từ Linh Tran", "lines": [{"en": "Thank you for confirming order 4821. Our office will be closed on June 12 for maintenance. Could you deliver the lamps the following day instead? The address and quantity remain unchanged.", "vi": "Cảm ơn đã xác nhận đơn 4821. Văn phòng chúng tôi sẽ đóng cửa ngày 12 tháng 6 để bảo trì. Bạn có thể giao đèn vào ngày hôm sau không? Địa chỉ và số lượng không đổi."}]}], "glossary": {"quantity": "số lượng", "unchanged": "không thay đổi", "maintenance": "bảo trì", "following": "tiếp theo", "lamps": "đèn"}}',1 WHERE NOT EXISTS(SELECT 1 FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:3]%' ORDER BY id LIMIT 1) AND sort_order=1);
INSERT INTO practice_questions(practice_set_id,passage_id,question_text,explanation,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:3]%' ORDER BY id LIMIT 1),(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:3]%' ORDER BY id LIMIT 1) AND sort_order=1 ORDER BY id LIMIT 1),'Why is Linh writing?','{"translation": "Vì sao Linh viết email?", "options_vi": {"A": "Hủy đơn", "B": "Yêu cầu ngày giao khác", "C": "Báo hàng hỏng", "D": "Đặt thêm đèn"}, "evidence": "Could you deliver the lamps the following day instead?", "explanation": "Email yêu cầu dời lịch giao vì văn phòng đóng cửa, không hủy đơn, báo hỏng hay tăng số lượng.", "analysis": {"A": "Không phù hợp với dẫn chứng: Hủy đơn. Email yêu cầu dời lịch giao vì văn phòng đóng cửa, không hủy đơn, báo hỏng hay tăng số lượng.", "B": "Đúng. Email yêu cầu dời lịch giao vì văn phòng đóng cửa, không hủy đơn, báo hỏng hay tăng số lượng.", "C": "Không phù hợp với dẫn chứng: Báo hàng hỏng. Email yêu cầu dời lịch giao vì văn phòng đóng cửa, không hủy đơn, báo hỏng hay tăng số lượng.", "D": "Không phù hợp với dẫn chứng: Đặt thêm đèn. Email yêu cầu dời lịch giao vì văn phòng đóng cửa, không hủy đơn, báo hỏng hay tăng số lượng."}}',147 WHERE NOT EXISTS(SELECT 1 FROM practice_questions WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:3]%' ORDER BY id LIMIT 1) AND passage_id=(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:3]%' ORDER BY id LIMIT 1) AND sort_order=1 ORDER BY id LIMIT 1) AND sort_order=147);
