INSERT INTO practice_questions(practice_set_id,passage_id,question_text,explanation,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:3]%' ORDER BY id LIMIT 1),(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:3]%' ORDER BY id LIMIT 1) AND sort_order=1 ORDER BY id LIMIT 1),'On what date does Linh want delivery?','{"translation": "Linh muốn giao vào ngày nào?", "options_vi": {"A": "11 tháng 6", "B": "12 tháng 6", "C": "13 tháng 6", "D": "18 tháng 6"}, "evidence": "Delivery: June 12, before noon. / Could you deliver the lamps the following day instead?", "explanation": "Đối chiếu xác nhận ngày 12 với the following day trong email: ngày tiếp theo là 13 tháng 6.", "analysis": {"A": "Không phù hợp với dẫn chứng: 11 tháng 6. Đối chiếu xác nhận ngày 12 với the following day trong email: ngày tiếp theo là 13 tháng 6.", "B": "Không phù hợp với dẫn chứng: 12 tháng 6. Đối chiếu xác nhận ngày 12 với the following day trong email: ngày tiếp theo là 13 tháng 6.", "C": "Đúng. Đối chiếu xác nhận ngày 12 với the following day trong email: ngày tiếp theo là 13 tháng 6.", "D": "Không phù hợp với dẫn chứng: 18 tháng 6. Đối chiếu xác nhận ngày 12 với the following day trong email: ngày tiếp theo là 13 tháng 6."}}',148 WHERE NOT EXISTS(SELECT 1 FROM practice_questions WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:3]%' ORDER BY id LIMIT 1) AND passage_id=(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:3]%' ORDER BY id LIMIT 1) AND sort_order=1 ORDER BY id LIMIT 1) AND sort_order=148);
