INSERT INTO practice_passages(practice_set_id,passage_text,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:4]%' ORDER BY id LIMIT 1),'{"title": "Conference Travel", "documents": [{"title": "Hotel offer", "title_vi": "Ưu đãi khách sạn", "lines": [{"en": "Harbor Hotel offers conference guests a nightly rate of $140, including breakfast. Free cancellation is available until September 5. A shuttle to the convention center leaves at 8 a.m. daily.", "vi": "Khách sạn Harbor có giá 140 đô la mỗi đêm cho khách hội nghị, gồm bữa sáng. Hủy miễn phí đến ngày 5 tháng 9. Xe đưa đón đến trung tâm hội nghị rời khách sạn lúc 8 giờ sáng hằng ngày."}]}, {"title": "Booking email", "title_vi": "Email đặt phòng", "lines": [{"en": "Please reserve two nights, September 10 and 11, for Ms. Patel at the conference rate. She will attend the opening session at 8:30 a.m. on September 11. Please confirm whether the shuttle arrives before then.", "vi": "Vui lòng đặt hai đêm 10 và 11 tháng 9 cho bà Patel theo giá hội nghị. Bà sẽ dự phiên khai mạc lúc 8 giờ 30 sáng ngày 11. Vui lòng xác nhận xe đưa đón có đến trước giờ đó không."}]}], "glossary": {"rate": "mức giá", "nightly": "mỗi đêm", "shuttle": "xe đưa đón", "cancellation": "việc hủy", "confirm": "xác nhận"}}',1 WHERE NOT EXISTS(SELECT 1 FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:4]%' ORDER BY id LIMIT 1) AND sort_order=1);
INSERT INTO practice_questions(practice_set_id,passage_id,question_text,explanation,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:4]%' ORDER BY id LIMIT 1),(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:4]%' ORDER BY id LIMIT 1) AND sort_order=1 ORDER BY id LIMIT 1),'What is the total room charge before any extra services?','{"translation": "Tổng tiền phòng trước dịch vụ thêm là bao nhiêu?", "options_vi": {"A": "140 đô la", "B": "280 đô la", "C": "300 đô la", "D": "420 đô la"}, "evidence": "A nightly rate of $140. / Please reserve two nights.", "explanation": "Hai đêm nhân 140 đô la bằng 280 đô la. Bữa sáng đã nằm trong giá.", "analysis": {"A": "Không phù hợp với dẫn chứng: 140 đô la. Hai đêm nhân 140 đô la bằng 280 đô la. Bữa sáng đã nằm trong giá.", "B": "Đúng. Hai đêm nhân 140 đô la bằng 280 đô la. Bữa sáng đã nằm trong giá.", "C": "Không phù hợp với dẫn chứng: 300 đô la. Hai đêm nhân 140 đô la bằng 280 đô la. Bữa sáng đã nằm trong giá.", "D": "Không phù hợp với dẫn chứng: 420 đô la. Hai đêm nhân 140 đô la bằng 280 đô la. Bữa sáng đã nằm trong giá."}}',147 WHERE NOT EXISTS(SELECT 1 FROM practice_questions WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:4]%' ORDER BY id LIMIT 1) AND passage_id=(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:4]%' ORDER BY id LIMIT 1) AND sort_order=1 ORDER BY id LIMIT 1) AND sort_order=147);
