INSERT INTO practice_questions(practice_set_id,passage_id,question_text,explanation,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:4]%' ORDER BY id LIMIT 1),(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:4]%' ORDER BY id LIMIT 1) AND sort_order=1 ORDER BY id LIMIT 1),'What information is requested but not supplied by the offer?','{"translation": "Thông tin nào được hỏi nhưng ưu đãi chưa cung cấp?", "options_vi": {"A": "Giá bữa sáng", "B": "Hạn hủy", "C": "Giờ xe đưa đón đến nơi", "D": "Giá phòng mỗi đêm"}, "evidence": "A shuttle ... leaves at 8 a.m. daily. / Please confirm whether the shuttle arrives before then.", "explanation": "Ưu đãi chỉ cho giờ xe khởi hành, không có thời gian đến trung tâm để biết có kịp 8 giờ 30 hay không.", "analysis": {"A": "Không phù hợp với dẫn chứng: Giá bữa sáng. Ưu đãi chỉ cho giờ xe khởi hành, không có thời gian đến trung tâm để biết có kịp 8 giờ 30 hay không.", "B": "Không phù hợp với dẫn chứng: Hạn hủy. Ưu đãi chỉ cho giờ xe khởi hành, không có thời gian đến trung tâm để biết có kịp 8 giờ 30 hay không.", "C": "Đúng. Ưu đãi chỉ cho giờ xe khởi hành, không có thời gian đến trung tâm để biết có kịp 8 giờ 30 hay không.", "D": "Không phù hợp với dẫn chứng: Giá phòng mỗi đêm. Ưu đãi chỉ cho giờ xe khởi hành, không có thời gian đến trung tâm để biết có kịp 8 giờ 30 hay không."}}',148 WHERE NOT EXISTS(SELECT 1 FROM practice_questions WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:4]%' ORDER BY id LIMIT 1) AND passage_id=(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:4]%' ORDER BY id LIMIT 1) AND sort_order=1 ORDER BY id LIMIT 1) AND sort_order=148);
