INSERT INTO practice_questions(practice_set_id,passage_id,question_text,explanation,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:4]%' ORDER BY id LIMIT 1),(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:4]%' ORDER BY id LIMIT 1) AND sort_order=1 ORDER BY id LIMIT 1),'Until when can the booking be canceled free of charge?','{"translation": "Có thể hủy miễn phí đến khi nào?", "options_vi": {"A": "5 tháng 9", "B": "10 tháng 9", "C": "11 tháng 9", "D": "12 tháng 9"}, "evidence": "Free cancellation is available until September 5.", "explanation": "Hạn hủy miễn phí là 5 tháng 9, không phải các ngày lưu trú.", "analysis": {"A": "Đúng. Hạn hủy miễn phí là 5 tháng 9, không phải các ngày lưu trú.", "B": "Không phù hợp với dẫn chứng: 10 tháng 9. Hạn hủy miễn phí là 5 tháng 9, không phải các ngày lưu trú.", "C": "Không phù hợp với dẫn chứng: 11 tháng 9. Hạn hủy miễn phí là 5 tháng 9, không phải các ngày lưu trú.", "D": "Không phù hợp với dẫn chứng: 12 tháng 9. Hạn hủy miễn phí là 5 tháng 9, không phải các ngày lưu trú."}}',149 WHERE NOT EXISTS(SELECT 1 FROM practice_questions WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:4]%' ORDER BY id LIMIT 1) AND passage_id=(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:4]%' ORDER BY id LIMIT 1) AND sort_order=1 ORDER BY id LIMIT 1) AND sort_order=149);
