INSERT INTO practice_questions(practice_set_id,passage_id,question_text,explanation,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:4]%' ORDER BY id LIMIT 1),(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:4]%' ORDER BY id LIMIT 1) AND sort_order=1 ORDER BY id LIMIT 1),'The word “rate” in the offer is closest in meaning to','{"translation": "Từ rate trong ưu đãi gần nghĩa nhất với", "options_vi": {"A": "tốc độ", "B": "đánh giá", "C": "tần suất", "D": "giá"}, "evidence": "A nightly rate of $140, including breakfast.", "explanation": "Trong ngữ cảnh phòng khách sạn và số tiền mỗi đêm, rate có nghĩa là mức giá.", "analysis": {"A": "Không phù hợp với dẫn chứng: tốc độ. Trong ngữ cảnh phòng khách sạn và số tiền mỗi đêm, rate có nghĩa là mức giá.", "B": "Không phù hợp với dẫn chứng: đánh giá. Trong ngữ cảnh phòng khách sạn và số tiền mỗi đêm, rate có nghĩa là mức giá.", "C": "Không phù hợp với dẫn chứng: tần suất. Trong ngữ cảnh phòng khách sạn và số tiền mỗi đêm, rate có nghĩa là mức giá.", "D": "Đúng. Trong ngữ cảnh phòng khách sạn và số tiền mỗi đêm, rate có nghĩa là mức giá."}}',150 WHERE NOT EXISTS(SELECT 1 FROM practice_questions WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:4]%' ORDER BY id LIMIT 1) AND passage_id=(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:4]%' ORDER BY id LIMIT 1) AND sort_order=1 ORDER BY id LIMIT 1) AND sort_order=150);
