INSERT INTO practice_sets(skill,part_no,title,instructions,difficulty,is_published) SELECT 'READING',7,'Part 7 — Cấp 5','[READING_PART7_LEVEL:5] Chọn đủ câu trong nhóm bài đọc để xem kết quả.','HARD',TRUE WHERE NOT EXISTS(SELECT 1 FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:5]%');
INSERT INTO practice_passages(practice_set_id,passage_text,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:5]%' ORDER BY id LIMIT 1),'{"title": "Supplier Selection", "documents": [{"title": "Request for quotations", "title_vi": "Yêu cầu báo giá", "lines": [{"en": "Northstar needs 40 ergonomic chairs delivered by November 20. The total budget is $8,000 including delivery. Suppliers must provide at least a three-year warranty.", "vi": "Northstar cần 40 ghế công thái học giao chậm nhất ngày 20 tháng 11. Ngân sách tổng là 8.000 đô la gồm giao hàng. Nhà cung cấp phải bảo hành ít nhất ba năm."}]}, {"title": "Two quotations", "title_vi": "Hai báo giá", "lines": [{"en": "Aster: $180 per chair; delivery $200; arrival November 18; warranty two years. Birch: $190 per chair; free delivery; arrival November 19; warranty three years.", "vi": "Aster: 180 đô la mỗi ghế; giao hàng 200 đô la; đến 18 tháng 11; bảo hành hai năm. Birch: 190 đô la mỗi ghế; giao miễn phí; đến 19 tháng 11; bảo hành ba năm."}]}, {"title": "Purchasing manager’s email", "title_vi": "Email quản lý mua hàng", "lines": [{"en": "Choose the supplier that meets all the requirements, even if another quotation is cheaper. Use the remaining budget to purchase floor protectors at $10 each. Do not exceed the original budget.", "vi": "Hãy chọn nhà cung cấp đáp ứng mọi yêu cầu, dù báo giá khác rẻ hơn. Dùng ngân sách còn lại mua miếng bảo vệ sàn giá 10 đô la mỗi chiếc. Không vượt ngân sách ban đầu."}]}], "glossary": {"quotation": "báo giá", "warranty": "bảo hành", "supplier": "nhà cung cấp", "remaining": "còn lại", "exceed": "vượt quá", "requirements": "các yêu cầu"}}',1 WHERE NOT EXISTS(SELECT 1 FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:5]%' ORDER BY id LIMIT 1) AND sort_order=1);
INSERT INTO practice_questions(practice_set_id,passage_id,question_text,explanation,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:5]%' ORDER BY id LIMIT 1),(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:5]%' ORDER BY id LIMIT 1) AND sort_order=1 ORDER BY id LIMIT 1),'Which supplier should be selected?','{"translation": "Nên chọn nhà cung cấp nào?", "options_vi": {"A": "Aster vì đến sớm hơn", "B": "Birch vì đáp ứng mọi yêu cầu", "C": "Cả hai chia đều đơn", "D": "Không ai vì đều vượt ngân sách"}, "evidence": "Suppliers must provide at least a three-year warranty. / Birch: ... warranty three years.", "explanation": "Birch đáp ứng bảo hành ba năm, giao trước hạn và tổng 7.600 đô la trong ngân sách. Aster chỉ bảo hành hai năm.", "analysis": {"A": "Không phù hợp với dẫn chứng: Aster vì đến sớm hơn. Birch đáp ứng bảo hành ba năm, giao trước hạn và tổng 7.600 đô la trong ngân sách. Aster chỉ bảo hành hai năm.", "B": "Đúng. Birch đáp ứng bảo hành ba năm, giao trước hạn và tổng 7.600 đô la trong ngân sách. Aster chỉ bảo hành hai năm.", "C": "Không phù hợp với dẫn chứng: Cả hai chia đều đơn. Birch đáp ứng bảo hành ba năm, giao trước hạn và tổng 7.600 đô la trong ngân sách. Aster chỉ bảo hành hai năm.", "D": "Không phù hợp với dẫn chứng: Không ai vì đều vượt ngân sách. Birch đáp ứng bảo hành ba năm, giao trước hạn và tổng 7.600 đô la trong ngân sách. Aster chỉ bảo hành hai năm."}}',147 WHERE NOT EXISTS(SELECT 1 FROM practice_questions WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:5]%' ORDER BY id LIMIT 1) AND passage_id=(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:5]%' ORDER BY id LIMIT 1) AND sort_order=1 ORDER BY id LIMIT 1) AND sort_order=147);
