INSERT INTO practice_options(question_id,option_label,option_text,is_correct) SELECT (SELECT id FROM practice_questions WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:5]%' ORDER BY id LIMIT 1) AND passage_id=(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:5]%' ORDER BY id LIMIT 1) AND sort_order=1 ORDER BY id LIMIT 1) AND sort_order=147 ORDER BY id LIMIT 1),'D','Neither, because both exceed the budget',FALSE WHERE NOT EXISTS(SELECT 1 FROM practice_options WHERE question_id=(SELECT id FROM practice_questions WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:5]%' ORDER BY id LIMIT 1) AND passage_id=(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:5]%' ORDER BY id LIMIT 1) AND sort_order=1 ORDER BY id LIMIT 1) AND sort_order=147 ORDER BY id LIMIT 1) AND option_label='D');
INSERT INTO practice_questions(practice_set_id,passage_id,question_text,explanation,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:5]%' ORDER BY id LIMIT 1),(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:5]%' ORDER BY id LIMIT 1) AND sort_order=1 ORDER BY id LIMIT 1),'Why is the cheaper quotation unsuitable?','{"translation": "Vì sao báo giá rẻ hơn không phù hợp?", "options_vi": {"A": "Giao muộn", "B": "Thiếu ghế", "C": "Bảo hành quá ngắn", "D": "Giao hàng không trong ngân sách"}, "evidence": "Aster: ... warranty two years. / Suppliers must provide at least a three-year warranty.", "explanation": "Aster không đạt thời hạn bảo hành tối thiểu ba năm. Ngày giao và tổng tiền vẫn đạt yêu cầu.", "analysis": {"A": "Không phù hợp với dẫn chứng: Giao muộn. Aster không đạt thời hạn bảo hành tối thiểu ba năm. Ngày giao và tổng tiền vẫn đạt yêu cầu.", "B": "Không phù hợp với dẫn chứng: Thiếu ghế. Aster không đạt thời hạn bảo hành tối thiểu ba năm. Ngày giao và tổng tiền vẫn đạt yêu cầu.", "C": "Đúng. Aster không đạt thời hạn bảo hành tối thiểu ba năm. Ngày giao và tổng tiền vẫn đạt yêu cầu.", "D": "Không phù hợp với dẫn chứng: Giao hàng không trong ngân sách. Aster không đạt thời hạn bảo hành tối thiểu ba năm. Ngày giao và tổng tiền vẫn đạt yêu cầu."}}',148 WHERE NOT EXISTS(SELECT 1 FROM practice_questions WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:5]%' ORDER BY id LIMIT 1) AND passage_id=(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:5]%' ORDER BY id LIMIT 1) AND sort_order=1 ORDER BY id LIMIT 1) AND sort_order=148);
