INSERT INTO practice_questions(practice_set_id,passage_id,question_text,explanation,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:5]%' ORDER BY id LIMIT 1),(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:5]%' ORDER BY id LIMIT 1) AND sort_order=1 ORDER BY id LIMIT 1),'How much remains after buying the selected chairs?','{"translation": "Còn bao nhiêu sau khi mua ghế được chọn?", "options_vi": {"A": "200 đô la", "B": "400 đô la", "C": "600 đô la", "D": "800 đô la"}, "evidence": "40 ergonomic chairs. / Birch: $190 per chair; free delivery. / The total budget is $8,000.", "explanation": "40 × 190 = 7.600; giao hàng miễn phí. Ngân sách còn 8.000 − 7.600 = 400 đô la.", "analysis": {"A": "Không phù hợp với dẫn chứng: 200 đô la. 40 × 190 = 7.600; giao hàng miễn phí. Ngân sách còn 8.000 − 7.600 = 400 đô la.", "B": "Đúng. 40 × 190 = 7.600; giao hàng miễn phí. Ngân sách còn 8.000 − 7.600 = 400 đô la.", "C": "Không phù hợp với dẫn chứng: 600 đô la. 40 × 190 = 7.600; giao hàng miễn phí. Ngân sách còn 8.000 − 7.600 = 400 đô la.", "D": "Không phù hợp với dẫn chứng: 800 đô la. 40 × 190 = 7.600; giao hàng miễn phí. Ngân sách còn 8.000 − 7.600 = 400 đô la."}}',149 WHERE NOT EXISTS(SELECT 1 FROM practice_questions WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:5]%' ORDER BY id LIMIT 1) AND passage_id=(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:5]%' ORDER BY id LIMIT 1) AND sort_order=1 ORDER BY id LIMIT 1) AND sort_order=149);
