INSERT INTO practice_questions(practice_set_id,passage_id,question_text,explanation,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:5]%' ORDER BY id LIMIT 1),(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:5]%' ORDER BY id LIMIT 1) AND sort_order=1 ORDER BY id LIMIT 1),'What is the maximum number of floor protectors that can be purchased?','{"translation": "Có thể mua tối đa bao nhiêu miếng bảo vệ sàn?", "options_vi": {"A": "20", "B": "30", "C": "40", "D": "80"}, "evidence": "Use the remaining budget to purchase floor protectors at $10 each.", "explanation": "Sau khi mua ghế Birch còn 400 đô la. Chia cho 10 đô la mỗi chiếc được tối đa 40 chiếc.", "analysis": {"A": "Không phù hợp với dẫn chứng: 20. Sau khi mua ghế Birch còn 400 đô la. Chia cho 10 đô la mỗi chiếc được tối đa 40 chiếc.", "B": "Không phù hợp với dẫn chứng: 30. Sau khi mua ghế Birch còn 400 đô la. Chia cho 10 đô la mỗi chiếc được tối đa 40 chiếc.", "C": "Đúng. Sau khi mua ghế Birch còn 400 đô la. Chia cho 10 đô la mỗi chiếc được tối đa 40 chiếc.", "D": "Không phù hợp với dẫn chứng: 80. Sau khi mua ghế Birch còn 400 đô la. Chia cho 10 đô la mỗi chiếc được tối đa 40 chiếc."}}',150 WHERE NOT EXISTS(SELECT 1 FROM practice_questions WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:5]%' ORDER BY id LIMIT 1) AND passage_id=(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:5]%' ORDER BY id LIMIT 1) AND sort_order=1 ORDER BY id LIMIT 1) AND sort_order=150);
