INSERT INTO practice_questions(practice_set_id,passage_id,question_text,explanation,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:5]%' ORDER BY id LIMIT 1),(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:5]%' ORDER BY id LIMIT 1) AND sort_order=1 ORDER BY id LIMIT 1),'What priority does the purchasing manager emphasize?','{"translation": "Quản lý mua hàng nhấn mạnh ưu tiên gì?", "options_vi": {"A": "Đáp ứng mọi tiêu chí", "B": "Chọn giao sớm nhất", "C": "Chọn giá thấp nhất bất kể bảo hành", "D": "Chi vượt ngân sách"}, "evidence": "Choose the supplier that meets all the requirements, even if another quotation is cheaper.", "explanation": "Email ưu tiên đáp ứng toàn bộ yêu cầu thay vì chỉ chọn giá thấp hoặc giao sớm; đồng thời cấm vượt ngân sách.", "analysis": {"A": "Đúng. Email ưu tiên đáp ứng toàn bộ yêu cầu thay vì chỉ chọn giá thấp hoặc giao sớm; đồng thời cấm vượt ngân sách.", "B": "Không phù hợp với dẫn chứng: Chọn giao sớm nhất. Email ưu tiên đáp ứng toàn bộ yêu cầu thay vì chỉ chọn giá thấp hoặc giao sớm; đồng thời cấm vượt ngân sách.", "C": "Không phù hợp với dẫn chứng: Chọn giá thấp nhất bất kể bảo hành. Email ưu tiên đáp ứng toàn bộ yêu cầu thay vì chỉ chọn giá thấp hoặc giao sớm; đồng thời cấm vượt ngân sách.", "D": "Không phù hợp với dẫn chứng: Chi vượt ngân sách. Email ưu tiên đáp ứng toàn bộ yêu cầu thay vì chỉ chọn giá thấp hoặc giao sớm; đồng thời cấm vượt ngân sách."}}',151 WHERE NOT EXISTS(SELECT 1 FROM practice_questions WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:5]%' ORDER BY id LIMIT 1) AND passage_id=(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:5]%' ORDER BY id LIMIT 1) AND sort_order=1 ORDER BY id LIMIT 1) AND sort_order=151);
